import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class AsyncCommunicationDemo {
    private final ExecutorService executor = Executors.newFixedThreadPool(4);

    public CompletableFuture<String> fetchRemoteDataAsync(String requestId) {
        return CompletableFuture.supplyAsync(() -> {
            // Simulate blocking I/O or downstream service call
            simulateNetworkLatency();
            if (requestId == null || requestId.isEmpty()) {
                throw new IllegalArgumentException("Invalid Request ID");
            }
            return "Data payload for: " + requestId;
        }, executor).handle((result, ex) -> {
            if (ex != null) {
                // Asynchronous exception handling boundary
                return "Fallback Data due to: " + ex.getMessage();
            }
            return result;
        });
    }

    private void simulateNetworkLatency() {
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
